    # block. The scattered object color is projected back toward that edge;
    # the first object met on a ray is marked 4.
    # Detect edge bars as runs (length >= 2) of a color distinct from the
    # background and scattered object color.
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    colors = {v for row in grid for v in row} - {bg}
    # Identify long edge runs, with their bar color.
    bars = []
    for r in range(h):
        for side, cols in [('left', range(w)), ('right', range(w-1, -1, -1))]:
            c0 = 0 if side == 'left' else w-1
            color = grid[r][c0]
            if color == bg:
                continue
            length = 0
            for c in cols:
                if grid[r][c] != color: break
                length += 1
            if length >= 2:
                bars.append((side, r, color, length))
    for c in range(w):
        for side, rows in [('top', range(h)), ('bottom', range(h-1, -1, -1))]:
            r0 = 0 if side == 'top' else h-1
